     5	// This function is created as PcapPlusPlus doesn't seem to offer a way of
     6	// parsing Pcap files directly from memory
     7	int dumpDataToPcapFile(const uint8_t *data, size_t size) {
     8	        FILE *fd;
     9	        int written = 0;
    10	
    11	        fd = fopen("/tmp/fuzz_sample.pcap", "wb");
    12	        if (fd == NULL) {
    13	                printf("Error opening pcap file for writing\n");
    14	                return -1;
    15	        }
