    29	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    30	
    31	        if (dumpDataToPcapFile(Data, Size) < 0) {
    32	                return 1;
    33	        }
    34	
    35	        // open a pcap file for reading
    36	        pcpp::PcapFileReaderDevice reader("/tmp/fuzz_sample.pcap");
    37	        if (!reader.open())
    38	        {
    39	                printf("Error opening the pcap file\n");
    40	                return 1;
    41	        }
    42	
    43	        // read the first (and only) packet from the file
    44	        pcpp::RawPacket rawPacket;
    45	        if (!reader.getNextPacket(rawPacket))
    46	        {
    47	                printf("Couldn't read the first packet in the file\n");
    48	                return 1;
    49	        }
    50	
    51	        // parse the raw packet into a parsed packet
    52	        pcpp::Packet parsedPacket(&rawPacket);
    53	
    54	        // verify the packet is IPv4
    55	        if (parsedPacket.isPacketOfType(pcpp::IPv4))
    56	        {
    57	                // extract source and dest IPs
    58	                pcpp::IPv4Address srcIP = parsedPacket.getLayerOfType<pcpp::IPv4Layer>()->getSrcIpAddress();
    59	                pcpp::IPv4Address destIP = parsedPacket.getLayerOfType<pcpp::IPv4Layer>()->getDstIpAddress();
    60	
    61	                // print source and dest IPs
    62	                printf("Source IP is '%s'; Dest IP is '%s'\n", srcIP.toString().c_str(), destIP.toString().c_str());
    63	        }
    64	
    65	        // close the file
